// Applied rules: [II_vec]
// Skipped rules: [III④: Hits [12, 13] are a backward, data-dependent paired read in a hot inner loop of an LZ-style backmatch routine. Although an L4-style bound exists via `min`, the access pattern cannot be expressed as a forward iterator/zip over slices; a slice rewrite would devolve to naive indexing with per-iteration bounds checks and would not improve alias information meaningfully for this pattern. Per rule III④ §5, abstain on backward/data-dependent hot-loop cursor accesses.]
#[inline(always)]
unsafe fn LZ4HC_countBack(
    ip_0: *const BYTE,
    match_0: *const BYTE,
    iMin: *const BYTE,
    mMin: *const BYTE,
) -> c_int {
    let mut back: c_int = 0 as c_int;
    let min: c_int = (if iMin.offset_from(ip_0) as c_long
        > mMin.offset_from(match_0) as c_long
    {
        iMin.offset_from(ip_0) as c_long
    } else {
        mMin.offset_from(match_0) as c_long
    }) as c_int;

    let limit4: c_int = min + 4 as c_int;
    let mut blocks4: c_int = if limit4 < 0 {
        ((-limit4) + 3 as c_int) / 4 as c_int
    } else {
        0 as c_int
    };
    while blocks4 > 0 {
        let cur_back = -(blocks4 * 4 as c_int) + 4 as c_int;
        let v: U32 = LZ4_read32(
            ip_0.offset(cur_back as isize)
                .offset(-(4 as c_int as isize))
                as *const c_void,
        ) as U32
            ^ LZ4_read32(
                match_0
                    .offset(cur_back as isize)
                    .offset(-(4 as c_int as isize))
                    as *const c_void,
            ) as U32;
        if v != 0 {
            return cur_back - LZ4HC_NbCommonBytes32(v) as c_int;
        }
        blocks4 -= 1;
    }

    back = -(if min < 0 {
        (-min) & !(4 as c_int - 1 as c_int)
    } else {
        0 as c_int
    });

    let mut remaining: c_int = back - min;
    while remaining > 0
        && *ip_0.offset((back - 1 as c_int) as isize) as c_int
            == *match_0.offset((back - 1 as c_int) as isize) as c_int
    {
        back -= 1;
        remaining -= 1;
    }
    return back;
}

